.mapping-subtree-toggle {
  position: absolute;
  z-index: 6;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--accent-primary) 25.000%, transparent);
  border-radius: 2px;
  background: var(--surface-raised);
  color: var(--fg);
  font: var(--text-md) var(--font-mono);
  white-space: pre;
  cursor: pointer;
  pointer-events: auto;
}
.mapping-subtree-toggle:hover, .mapping-subtree-toggle:focus-visible {
  border-color: var(--accent, var(--accent-primary));
  color: var(--accent, var(--accent-primary));
}
.mapping-subtree-toggle:disabled { opacity: .4; cursor: default; }
